import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, float, fract, sin, dot, clamp } from 'three/tsl';
import { gsap } from 'gsap';

function hexToRgb01(hex) {
  const h = hex.replace('#', '');
  const r = parseInt(h.substring(0, 2), 16) / 255;
  const g = parseInt(h.substring(2, 4), 16) / 255;
  const b = parseInt(h.substring(4, 6), 16) / 255;
  return [r, g, b];
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, DoubleSide } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const inkRgb = hexToRgb01(colors.ink);
  const surfaceRgb = hexToRgb01(colors.surface);
  const paperColor = colors.paper ?? '#e8ecf2';

  const root = new Group();
  root.name = 'hero-subhead';

  // --- backdrop card: engineered gradient + subtle grain, behind the image plane ---
  const cardWidth = 3.0;
  const cardHeight = 0.95;

  const gradientMaterial = new MeshBasicNodeMaterial();
  gradientMaterial.transparent = true;
  gradientMaterial.opacity = 0;

  const uvNode = uv();
  const gradient = mix(vec3(...surfaceRgb), vec3(...inkRgb), clamp(uvNode.y, 0.0, 1.0));

  // cheap deterministic grain (no time dependency — static composition)
  const grainSeed = dot(uvNode, vec3(12.9898, 78.233, 0.0).xy ? uvNode : uvNode, );
  const grainHash = fract(sin(dot(uvNode, vec3(12.9898, 78.233, 0.0).xy)).mul(43758.5453));
  const grain = grainHash.sub(0.5).mul(0.035);

  gradientMaterial.colorNode = gradient.add(grain);

  const gradientGeo = new PlaneGeometry(cardWidth, cardHeight);
  const gradientMesh = new Mesh(gradientGeo, gradientMaterial);
  gradientMesh.position.set(0, 0, -0.04);
  gradientMesh.renderOrder = 0;
  root.add(gradientMesh);

  // --- image plane (cta-hero-isolated.png) — atlas rect 512x320, aspect 1.6:1 ---
  const aspect = 512 / 320;
  const imgWidth = 2.0;
  const imgHeight = imgWidth / aspect;

  const imageMaterial = new MeshBasicNodeMaterial();
  imageMaterial.transparent = true;
  imageMaterial.opacity = 0;
  imageMaterial.side = DoubleSide;
  imageMaterial.colorNode = mix(vec3(...inkRgb), vec3(1.0, 1.0, 1.0), 0.85);

  const imageGeo = new PlaneGeometry(imgWidth, imgHeight);
  const imageMesh = new Mesh(imageGeo, imageMaterial);
  imageMesh.position.set(-0.55, 0.0, -0.01);
  imageMesh.renderOrder = 1;
  root.add(imageMesh);

  let loadedTexture = null;
  let textureLoadPromise = null;
  if (config.imageUrl) {
    textureLoadPromise = ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        loadedTexture = tex;
        imageMaterial.map = tex;
        imageMaterial.colorNode = null;
        imageMaterial.needsUpdate = true;
      })
      .catch(() => {
        // keep the ink-tinted fallback plane if the asset fails to load
      });
  }

  // --- text content (verbatim, ASCII-safe) ---
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const textGroup = new Group();
  textGroup.position.set(0.35, 0.0, 0.02);
  root.add(textGroup);

  const createdTextNodes = [];
  for (const item of items) {
    const raw = typeof item.text === 'string' ? item.text : '';
    const safe = raw.replace(/\u2014/g, '-').replace(/\u00b7/g, '-').replace(/[^\x00-\x7F]/g, '-');
    const fontSize = item.typography?.fontSize ?? 42;
    const textNode = ctx.fontAtlas.createText(safe, {
      fontSize,
      color: paperColor,
      align: 'left',
      maxWidthPx: 460,
      letterSpacingPx: 0.5,
    });
    textNode.position.set(0, 0, 0);
    textGroup.add(textNode);
    createdTextNodes.push(textNode);
  }

  // --- entrance motion: weighted, single settle, no perpetual idle motion ---
  root.position.y -= 0.2;
  gradientMesh.scale.setScalar(0.98);
  imageMesh.scale.setScalar(0.98);

  const tl = gsap.timeline();
  tl.to(root.position, {
    y: root.position.y + 0.2,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  tl.to(gradientMaterial, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0.05);
  tl.to(imageMaterial, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0.1);
  tl.to([gradientMesh.scale, imageMesh.scale], {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  }, 0.05);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(gradientMaterial);
    gsap.killTweensOf(imageMaterial);
    gsap.killTweensOf(gradientMesh.scale);
    gsap.killTweensOf(imageMesh.scale);

    gradientGeo.dispose();
    gradientMaterial.dispose();
    imageGeo.dispose();
    imageMaterial.dispose();

    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }

    for (const node of createdTextNodes) {
      node.traverse?.((child) => {
        if (child.geometry) child.geometry.dispose?.();
        if (child.material) {
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          mats.forEach((m) => m.dispose?.());
        }
      });
    }

    textureLoadPromise = null;
  };

  return root;
}
